package eventbus

import (
	"testing"
	"sync"
)

func TestSubscribeAndPublish(t *testing.T) {
	bus := New()
	called := false
	bus.Subscribe("greet", func(p interface{}) {
		if p.(string) != "hello" {
			t.Fatalf("want hello, got %v", p)
		}
		called = true
	})
	bus.Publish("greet", "hello")
	if !called {
		t.Fatal("handler not called")
	}
}

func TestUnsubscribe(t *testing.T) {
	bus := New()
	count := 0
	id := bus.Subscribe("ev", func(_ interface{}) { count++ })
	bus.Publish("ev", nil)
	bus.Unsubscribe("ev", id)
	bus.Publish("ev", nil)
	if count != 1 {
		t.Fatalf("want 1 call, got %d", count)
	}
}

func TestMultipleSubscribers(t *testing.T) {
	bus := New()
	var mu sync.Mutex
	results := []string{}
	bus.Subscribe("t", func(_ interface{}) { mu.Lock(); results = append(results, "a"); mu.Unlock() })
	bus.Subscribe("t", func(_ interface{}) { mu.Lock(); results = append(results, "b"); mu.Unlock() })
	bus.Publish("t", nil)
	if len(results) != 2 {
		t.Fatalf("want 2 results, got %d", len(results))
	}
}

func TestPublishNoSubscribers(t *testing.T) {
	bus := New()
	bus.Publish("empty", "data") // should not panic
}

func TestSubscribeReturnsDifferentIDs(t *testing.T) {
	bus := New()
	id1 := bus.Subscribe("x", func(_ interface{}) {})
	id2 := bus.Subscribe("x", func(_ interface{}) {})
	if id1 == id2 {
		t.Fatal("IDs should be unique")
	}
}
